CREATE TABLE IF NOT EXISTS `data_sources` (`id` varchar(36) NOT NULL, `name` varchar(160) NOT NULL, `description` text, `database_type` varchar(40) NOT NULL DEFAULT 'ORACLE', `environment` enum('DEVELOPMENT','TEST','UAT','PRODUCTION') NOT NULL, `status` enum('DRAFT','ACTIVE','INACTIVE','CONNECTION_ERROR','ARCHIVED') NOT NULL DEFAULT 'DRAFT', `host` varchar(255) NOT NULL, `port` int NOT NULL DEFAULT 1521, `connection_mode` enum('SERVICE_NAME','SID','CONNECTION_STRING') NOT NULL DEFAULT 'SERVICE_NAME', `service_name` varchar(255), `sid` varchar(255), `connection_string` text, `username` varchar(255) NOT NULL, `encrypted_password` longtext NOT NULL, `password_iv` varchar(64) NOT NULL, `password_auth_tag` varchar(64) NOT NULL, `default_schema` varchar(128), `allowed_schemas` longtext, `connection_timeout_seconds` int NOT NULL DEFAULT 10, `query_timeout_seconds` int NOT NULL DEFAULT 30, `connection_status` enum('NOT_TESTED','CONNECTED','FAILED','TIMEOUT') NOT NULL DEFAULT 'NOT_TESTED', `metadata_sync_status` enum('NOT_SYNCED','SYNCING','SYNCED','PARTIAL','FAILED') NOT NULL DEFAULT 'NOT_SYNCED', `last_connection_test_at` datetime(3), `last_successful_connection_at` datetime(3), `last_metadata_sync_at` datetime(3), `database_version` varchar(255), `owner_user_id` varchar(36) NOT NULL, `created_by` varchar(36) NOT NULL, `updated_by` varchar(36) NOT NULL, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `archived_at` datetime(3), PRIMARY KEY (`id`), UNIQUE KEY `data_sources_name_environment_uq` (`name`,`environment`), KEY `data_sources_status_idx` (`status`), KEY `data_sources_owner_idx` (`owner_user_id`), CONSTRAINT `data_sources_owner_fk` FOREIGN KEY (`owner_user_id`) REFERENCES `users` (`id`));
CREATE TABLE IF NOT EXISTS `data_source_schemas` (`id` varchar(36) NOT NULL, `data_source_id` varchar(36) NOT NULL, `schema_name` varchar(128) NOT NULL, `table_count` int NOT NULL DEFAULT 0, `view_count` int NOT NULL DEFAULT 0, `is_included` boolean NOT NULL DEFAULT false, `status` enum('ACTIVE','MISSING','EXCLUDED','ARCHIVED') NOT NULL DEFAULT 'ACTIVE', `last_synced_at` datetime(3), `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `data_source_schemas_uq` (`data_source_id`,`schema_name`), CONSTRAINT `data_source_schemas_source_fk` FOREIGN KEY (`data_source_id`) REFERENCES `data_sources` (`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `data_source_tables` (`id` varchar(36) NOT NULL, `data_source_id` varchar(36) NOT NULL, `schema_id` varchar(36), `schema_name` varchar(128) NOT NULL, `table_name` varchar(128) NOT NULL, `business_name` varchar(255), `object_type` enum('TABLE','VIEW') NOT NULL, `description` text, `estimated_row_count` int, `last_analyzed_at` datetime(3), `is_partitioned` boolean NOT NULL DEFAULT false, `is_temporary` boolean NOT NULL DEFAULT false, `is_included` boolean NOT NULL DEFAULT true, `status` enum('ACTIVE','MISSING','EXCLUDED','ARCHIVED') NOT NULL DEFAULT 'ACTIVE', `metadata_hash` varchar(64), `last_synced_at` datetime(3), `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `data_source_tables_uq` (`data_source_id`,`schema_name`,`table_name`), KEY `data_source_tables_source_idx` (`data_source_id`), CONSTRAINT `data_source_tables_source_fk` FOREIGN KEY (`data_source_id`) REFERENCES `data_sources` (`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `data_source_columns` (`id` varchar(36) NOT NULL, `table_id` varchar(36) NOT NULL, `column_name` varchar(128) NOT NULL, `business_name` varchar(255), `description` text, `data_type` varchar(128) NOT NULL, `data_length` int, `numeric_precision` int, `numeric_scale` int, `nullable` boolean NOT NULL DEFAULT true, `default_value` text, `ordinal_position` int NOT NULL, `is_primary_key` boolean NOT NULL DEFAULT false, `is_foreign_key` boolean NOT NULL DEFAULT false, `is_included` boolean NOT NULL DEFAULT true, `sensitivity_type` enum('NONE','PERSONAL_DATA','SENSITIVE_PERSONAL_DATA','FINANCIAL','CREDENTIAL','CONTACT','IDENTIFIER','CONFIDENTIAL') NOT NULL DEFAULT 'NONE', `masking_rule` varchar(80), `metadata_hash` varchar(64), `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `data_source_columns_uq` (`table_id`,`column_name`), CONSTRAINT `data_source_columns_table_fk` FOREIGN KEY (`table_id`) REFERENCES `data_source_tables` (`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `data_source_access` (`id` varchar(36) NOT NULL, `data_source_id` varchar(36) NOT NULL, `user_id` varchar(36), `role` enum('ADMIN','DATA_SOURCE_CREATOR','DASHBOARD_CREATOR','VIEWER'), `permission` enum('VIEW_METADATA','PREVIEW_DATA','USE_FOR_DASHBOARD','EDIT_METADATA','MANAGE_CONNECTION','SYNC_METADATA') NOT NULL, `granted_by` varchar(36) NOT NULL, `granted_at` datetime(3) NOT NULL, `revoked_at` datetime(3), PRIMARY KEY (`id`), KEY `data_source_access_source_idx` (`data_source_id`), KEY `data_source_access_user_idx` (`user_id`), CONSTRAINT `data_source_access_source_fk` FOREIGN KEY (`data_source_id`) REFERENCES `data_sources` (`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `data_source_connection_tests` (`id` varchar(36) NOT NULL, `data_source_id` varchar(36) NOT NULL, `status` enum('NOT_TESTED','CONNECTED','FAILED','TIMEOUT') NOT NULL, `response_time_ms` int, `database_version` varchar(255), `current_user` varchar(255), `current_schema` varchar(255), `error_code` varchar(32), `error_category` varchar(80), `error_message` varchar(255), `tested_by` varchar(36) NOT NULL, `ip_address` varchar(64), `request_id` varchar(36) NOT NULL, `tested_at` datetime(3) NOT NULL, PRIMARY KEY (`id`), KEY `connection_tests_source_idx` (`data_source_id`), CONSTRAINT `connection_tests_source_fk` FOREIGN KEY (`data_source_id`) REFERENCES `data_sources` (`id`) ON DELETE CASCADE);
